    <script>
      const filterButtons = document.querySelectorAll(".filter-chip");
      const dealCards = document.querySelectorAll(".deal-card");
      const dealResults = document.getElementById("deal-results");
      const addToBagButtons = document.querySelectorAll(".add-to-bag");
      const cartStatus = document.getElementById("cart-status");
      const signupForm = document.getElementById("signup-form");
      const signupStatus = document.getElementById("signup-status");

      function updateDealResults(filter) {
        let visibleCount = 0;

        dealCards.forEach((card) => {
          const matches = filter === "all" || card.dataset.category === filter;
          card.hidden = !matches;

          if (matches) {
            visibleCount += 1;
          }
        });

        const label =
          filter === "all"
            ? `Showing ${visibleCount} deals.`
            : `Showing ${visibleCount} ${filter} deal${visibleCount === 1 ? "" : "s"}.`;

        dealResults.textContent = label;
      }

      filterButtons.forEach((button) => {
        button.addEventListener("click", () => {
          filterButtons.forEach((chip) => {
            const isActive = chip === button;
            chip.classList.toggle("is-active", isActive);
            chip.setAttribute("aria-pressed", String(isActive));
          });

          updateDealResults(button.dataset.filter);
        });
      });

      addToBagButtons.forEach((button) => {
        button.addEventListener("click", () => {
          const productName = button.dataset.product;
          cartStatus.textContent = `${productName} added to bag.`;
        });
      });

      signupForm.addEventListener("submit", (event) => {
        event.preventDefault();

        const emailInput = signupForm.elements.email;

        if (!(emailInput instanceof HTMLInputElement)) {
          return;
        }

        if (!emailInput.checkValidity()) {
          emailInput.setAttribute("aria-invalid", "true");
          signupStatus.textContent = "Enter a valid email address to join Velora membership.";
          emailInput.focus();
          return;
        }

        emailInput.setAttribute("aria-invalid", "false");
        signupStatus.textContent = `Thanks for joining, ${emailInput.value}. Weekly drops are on the way.`;
        signupForm.reset();
        emailInput.setAttribute("aria-invalid", "false");
      });

      updateDealResults("all");
    </script>
